      document.getElementById('analysisOverviewProgress').setAttribute('style', 'width:' + 20 + '%' );
      document.getElementById('analysisOverviewProgress').innerHTML = 'Calculating QED weighting factors specific to this histogram file...';

      // initialize fast acos lookup table
      dataStore.ACOS_LUT_SIZE = 512;
      dataStore.acosTable = new Float64Array(dataStore.ACOS_LUT_SIZE);

      // Populate the table with precomputed values spanning from -1 to 1
      for(let i = 0; i < dataStore.ACOS_LUT_SIZE; i++){
        // Map index [0 to 511] to the range [-1.0 to 1.0]
        const x = (i / (dataStore.ACOS_LUT_SIZE - 1)) * 2 - 1;
        dataStore.acosTable[i] = Math.acos(x);
      }
      console.log(dataStore);

      // This histogram captures all coincidences with satisfy 180 degree scatters of 511keV gamma rays in this run
      // We produce essentially an event-mixed spectrum by multiplying the values for each pixel which satisfy the 180 degree condition
      // "COMP_QED_GE_weights"
      console.log(dataStore);
      thisKey = dataStore.histoFileName.split(".")[0] + ":" + "COMP_QED_GE_weights_indiv";
      //thisKey = dataStore.histoFileName.split(".")[0] + ":" + "COMP_QED_GE_weights_coinc";
      var weightsArray = [];
